package io.github.diodeme.ji.session.codec.json;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.SessionSnapshot;
import io.github.diodeme.ji.session.tree.SessionCodec;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Explicit JSON encoding adapter for canonical Session documents. */
public final class JacksonSessionCodec implements SessionCodec {
    private final ObjectMapper mapper = new ObjectMapper();

    @Override
    public byte[] encode(SessionDocument document) {
        try {
            ObjectNode root = mapper.createObjectNode();
            root.put("schemaVersion", document.schemaVersion());
            root.set("metadata", metadata(document.metadata()));
            root.put("revision", document.revision());
            root.put("nextSequence", document.nextSequence());
            ArrayNode log = root.putArray("log");
            document.log().forEach(mutation -> log.add(mutation(mutation)));
            root.set("model", model(document.model()));
            root.put("workingDirectory", document.workingDirectory());
            root.set("usage", usage(document.usage()));
            document.activeRun().ifPresent(run -> root.set("activeRun", activeRun(run)));
            ArrayNode compactions = root.putArray("compactions");
            document.compactions().forEach(value -> compactions.add(compaction(value)));
            return mapper.writeValueAsBytes(root);
        } catch (IOException exception) {
            throw new IllegalStateException("Session document cannot be encoded", exception);
        }
    }

    @Override
    public SessionDocument decode(byte[] encoded) {
        try {
            JsonNode root = mapper.readTree(encoded);
            return new SessionDocument(requiredInt(root, "schemaVersion"), decodeMetadata(root.get("metadata")),
                    requiredLong(root, "revision"), requiredLong(root, "nextSequence"),
                    decodeMutations(root.get("log")), decodeModel(root.get("model")),
                    requiredText(root, "workingDirectory"), decodeUsage(root.get("usage")),
                    decodeActiveRun(root.get("activeRun")), decodeCompactions(root.get("compactions")));
        } catch (IOException | RuntimeException exception) {
            throw new IllegalStateException("Session document cannot be decoded", exception);
        }
    }

    private ObjectNode metadata(SessionDocument.Metadata value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("sessionId", value.sessionId());
        node.put("createdAt", value.createdAt().toString());
        value.parentSessionId().ifPresent(parent -> node.put("parentSessionId", parent));
        return node;
    }

    private ObjectNode mutation(SessionDocument.Mutation value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("sequence", value.sequence());
        if (value instanceof SessionDocument.EntryMutation entry) {
            node.put("kind", "entry");
            entry.lane().ifPresent(lane -> node.put("lane", lane));
            node.set("entry", entry(entry.entry()));
        } else if (value instanceof SessionDocument.RecordMutation record) {
            node.put("kind", "record");
            node.set("record", record(record.record()));
        } else if (value instanceof SessionDocument.LaneMutation lane) {
            node.put("kind", "lane");
            node.put("operation", lane.kind().name());
            node.put("lane", lane.lane());
            lane.leafEntryId().ifPresent(id -> node.put("leafEntryId", id));
        } else if (value instanceof SessionDocument.NameFactMutation fact) {
            node.put("kind", "name");
            fact.name().ifPresent(name -> node.put("name", name));
        } else if (value instanceof SessionDocument.LabelFactMutation fact) {
            node.put("kind", "label");
            node.put("entryId", fact.entryId());
            fact.label().ifPresent(label -> node.put("label", label));
        }
        return node;
    }

    private ObjectNode entry(SessionDocument.Entry value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("id", value.id());
        value.parentId().ifPresent(parent -> node.put("parentId", parent));
        node.put("createdAt", value.createdAt().toString());
        node.put("kind", value.kind().name());
        value.message().ifPresent(message -> node.set("message", message(message)));
        node.set("data", mapper.valueToTree(value.data()));
        return node;
    }

    private ObjectNode record(SessionDocument.Record value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("id", value.id());
        node.put("lane", value.lane());
        node.put("kind", value.kind().name());
        value.operationId().ifPresent(id -> node.put("operationId", id));
        value.operationKind().ifPresent(kind -> node.put("operationKind", kind.name()));
        value.outcome().ifPresent(outcome -> node.put("outcome", outcome.name()));
        node.set("data", mapper.valueToTree(value.data()));
        node.put("createdAt", value.createdAt().toString());
        return node;
    }

    private ObjectNode message(Message value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("id", value.id());
        node.put("role", value.role().name());
        ArrayNode content = node.putArray("content");
        for (Content block : value.content()) {
            ObjectNode item = mapper.createObjectNode();
            if (block instanceof Content.Text text) {
                item.put("type", "text");
                item.put("text", text.text());
            } else if (block instanceof Content.ToolCall call) {
                item.put("type", "toolCall");
                item.put("id", call.id());
                item.put("name", call.name());
                item.set("arguments", mapper.valueToTree(call.arguments()));
            }
            content.add(item);
        }
        value.toolCallId().ifPresent(id -> node.put("toolCallId", id));
        node.put("createdAt", value.createdAt().toString());
        return node;
    }

    private ObjectNode model(ModelRef value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("provider", value.provider());
        node.put("model", value.model());
        return node;
    }

    private ObjectNode usage(Usage value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("inputTokens", value.inputTokens());
        node.put("outputTokens", value.outputTokens());
        node.put("cacheReadTokens", value.cacheReadTokens());
        node.put("cacheWriteTokens", value.cacheWriteTokens());
        node.put("costMicros", value.costMicros());
        return node;
    }

    private ObjectNode activeRun(SessionSnapshot.ActiveRun value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("runId", value.runId());
        node.put("status", value.status().name());
        node.put("revision", value.revision());
        return node;
    }

    private ObjectNode compaction(SessionDocument.CompactionCheckpoint value) {
        ObjectNode node = mapper.createObjectNode();
        node.put("compactionId", value.compactionId());
        node.put("lane", value.lane());
        node.put("status", value.status().name());
        node.put("revision", value.revision());
        node.put("attempt", value.attempt());
        node.put("resultEntryId", value.resultEntryId());
        value.summary().ifPresent(summary -> node.put("summary", summary));
        ArrayNode retained = node.putArray("retainedTail");
        value.retainedTail().forEach(message -> retained.add(message(message)));
        node.put("tokensBefore", value.tokensBefore());
        node.set("usage", usage(value.usage()));
        return node;
    }

    private SessionDocument.Metadata decodeMetadata(JsonNode node) {
        return new SessionDocument.Metadata(requiredText(node, "sessionId"),
                Instant.parse(requiredText(node, "createdAt")), optionalText(node, "parentSessionId"));
    }

    private List<SessionDocument.Mutation> decodeMutations(JsonNode node) {
        requireArray(node, "log");
        var result = new ArrayList<SessionDocument.Mutation>();
        for (JsonNode value : node) {
            long sequence = requiredLong(value, "sequence");
            switch (requiredText(value, "kind")) {
                case "entry" -> result.add(new SessionDocument.EntryMutation(sequence,
                        optionalText(value, "lane"), decodeEntry(value.get("entry"))));
                case "record" -> result.add(new SessionDocument.RecordMutation(sequence, decodeRecord(value.get("record"))));
                case "lane" -> result.add(new SessionDocument.LaneMutation(sequence,
                        SessionDocument.LaneMutationKind.valueOf(requiredText(value, "operation")),
                        requiredText(value, "lane"), optionalText(value, "leafEntryId")));
                case "name" -> result.add(new SessionDocument.NameFactMutation(sequence, optionalText(value, "name")));
                case "label" -> result.add(new SessionDocument.LabelFactMutation(sequence,
                        requiredText(value, "entryId"), optionalText(value, "label")));
                default -> throw new IllegalArgumentException("unknown Session mutation kind");
            }
        }
        return List.copyOf(result);
    }

    private SessionDocument.Entry decodeEntry(JsonNode node) {
        return new SessionDocument.Entry(requiredText(node, "id"), optionalText(node, "parentId"),
                Instant.parse(requiredText(node, "createdAt")),
                SessionDocument.EntryKind.valueOf(requiredText(node, "kind")), decodeMessage(node.get("message")),
                objectMap(node.get("data")));
    }

    private SessionDocument.Record decodeRecord(JsonNode node) {
        return new SessionDocument.Record(requiredText(node, "id"), requiredText(node, "lane"),
                SessionDocument.RecordKind.valueOf(requiredText(node, "kind")), optionalText(node, "operationId"),
                optionalEnum(node, "operationKind", SessionDocument.OperationKind.class),
                optionalEnum(node, "outcome", SessionDocument.OperationOutcome.class), objectMap(node.get("data")),
                Instant.parse(requiredText(node, "createdAt")));
    }

    private Optional<Message> decodeMessage(JsonNode node) {
        if (node == null || node.isNull()) return Optional.empty();
        var content = new ArrayList<Content>();
        requireArray(node.get("content"), "content");
        for (JsonNode item : node.get("content")) {
            switch (requiredText(item, "type")) {
                case "text" -> content.add(new Content.Text(requiredText(item, "text")));
                case "toolCall" -> content.add(new Content.ToolCall(requiredText(item, "id"),
                        requiredText(item, "name"), objectMap(item.get("arguments"))));
                default -> throw new IllegalArgumentException("unknown content type");
            }
        }
        return Optional.of(new Message(requiredText(node, "id"), Message.Role.valueOf(requiredText(node, "role")),
                content, optionalText(node, "toolCallId"), Instant.parse(requiredText(node, "createdAt"))));
    }

    private ModelRef decodeModel(JsonNode node) {
        return new ModelRef(requiredText(node, "provider"), requiredText(node, "model"));
    }

    private Usage decodeUsage(JsonNode node) {
        return new Usage(requiredLong(node, "inputTokens"), requiredLong(node, "outputTokens"),
                requiredLong(node, "cacheReadTokens"), requiredLong(node, "cacheWriteTokens"),
                requiredLong(node, "costMicros"));
    }

    private Optional<SessionSnapshot.ActiveRun> decodeActiveRun(JsonNode node) {
        if (node == null || node.isNull()) return Optional.empty();
        return Optional.of(new SessionSnapshot.ActiveRun(requiredText(node, "runId"),
                SessionSnapshot.Status.valueOf(requiredText(node, "status")), requiredLong(node, "revision")));
    }

    private List<SessionDocument.CompactionCheckpoint> decodeCompactions(JsonNode node) {
        requireArray(node, "compactions");
        var result = new ArrayList<SessionDocument.CompactionCheckpoint>();
        for (JsonNode value : node) {
            var retained = new ArrayList<Message>();
            requireArray(value.get("retainedTail"), "retainedTail");
            for (JsonNode message : value.get("retainedTail")) retained.add(decodeMessage(message).orElseThrow());
            result.add(new SessionDocument.CompactionCheckpoint(requiredText(value, "compactionId"),
                    requiredText(value, "lane"), SessionDocument.CompactionStatus.valueOf(requiredText(value, "status")),
                    requiredLong(value, "revision"), requiredInt(value, "attempt"),
                    requiredText(value, "resultEntryId"), optionalText(value, "summary"), retained,
                    requiredLong(value, "tokensBefore"), decodeUsage(value.get("usage"))));
        }
        return List.copyOf(result);
    }

    private Map<String, Object> objectMap(JsonNode node) {
        if (node == null || !node.isObject()) throw new IllegalArgumentException("expected JSON object");
        var result = new LinkedHashMap<String, Object>();
        Iterator<Map.Entry<String, JsonNode>> fields = node.properties().iterator();
        fields.forEachRemaining(entry -> result.put(entry.getKey(), mapper.convertValue(entry.getValue(), Object.class)));
        return result;
    }

    private static void requireArray(JsonNode node, String field) {
        if (node == null || !node.isArray()) throw new IllegalArgumentException(field + " must be an array");
    }

    private static String requiredText(JsonNode node, String field) {
        JsonNode value = node == null ? null : node.get(field);
        if (value == null || !value.isTextual()) throw new IllegalArgumentException(field + " must be text");
        return value.textValue();
    }

    private static Optional<String> optionalText(JsonNode node, String field) {
        JsonNode value = node == null ? null : node.get(field);
        return value == null || value.isNull() ? Optional.empty() : Optional.of(requiredText(node, field));
    }

    private static long requiredLong(JsonNode node, String field) {
        JsonNode value = node == null ? null : node.get(field);
        if (value == null || !value.canConvertToLong()) throw new IllegalArgumentException(field + " must be an integer");
        return value.longValue();
    }

    private static int requiredInt(JsonNode node, String field) {
        long value = requiredLong(node, field);
        if (value < Integer.MIN_VALUE || value > Integer.MAX_VALUE) throw new IllegalArgumentException(field + " is out of range");
        return (int) value;
    }

    private static <T extends Enum<T>> Optional<T> optionalEnum(JsonNode node, String field, Class<T> type) {
        return optionalText(node, field).map(value -> Enum.valueOf(type, value));
    }
}

